<hlm-sidebar-wrapper class="app">
  <hlm-sidebar>
    <div hlmSidebarHeader class="app__brand">
      <ng-icon hlmIcon name="lucideShield" />
      <span hlmLarge>Hero Ops</span>
    </div>

    <div hlmSidebarContent>
      <div hlmSidebarGroup>
        <div hlmSidebarGroupLabel>Operations</div>
        <div hlmSidebarGroupContent>
          <nav aria-label="Primary">
            <ul hlmSidebarMenu>
              @for (item of vm.navItems; track item.path) {
                <li hlmSidebarMenuItem>
                  <a
                    hlmSidebarMenuButton
                    [routerLink]="item.path"
                    routerLinkActive
                    #active="routerLinkActive"
                    [isActive]="active.isActive"
                    [tooltip]="item.label"
                  >
                    <ng-icon hlmIcon [name]="item.icon" />
                    <span>{{ item.label }}</span>
                  </a>
                </li>
              }
            </ul>
          </nav>
        </div>
      </div>
    </div>

    <div hlmSidebarFooter>
      <div class="app__operator">
        <hlm-avatar>
          <span hlmAvatarFallback>OC</span>
        </hlm-avatar>
        <span hlmSmall>Ops Commander</span>
      </div>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset class="app__main">
    <header class="app__topbar">
      <button hlmSidebarTrigger></button>

      <nav aria-label="Breadcrumb" class="app__crumbs">
        <ol class="app__crumb-list">
          @for (crumb of vm.crumbs(); track $index; let last = $last) {
            <li class="app__crumb">
              @if (last) {
                <span hlmSmall aria-current="page">{{ crumb.label }}</span>
              } @else {
                <a hlmSmall [routerLink]="crumb.link">{{ crumb.label }}</a>
                <ng-icon hlmIcon name="lucideChevronRight" tone="muted" aria-hidden="true" />
              }
            </li>
          }
        </ol>
      </nav>

      <div role="search" class="app__search">
        <ng-icon hlmIcon name="lucideSearch" tone="muted" aria-hidden="true" />
        <input
          hlmInput
          type="search"
          class="app__search-input"
          aria-label="Search heroes and missions"
          placeholder="Search heroes and missions"
        />
      </div>

      <div class="app__actions">
        <button
          hlmBtn
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Notifications"
          hlmTooltip="Notifications"
        >
          <ng-icon hlmIcon name="lucideBell" />
        </button>

        <button
          hlmBtn
          type="button"
          variant="ghost"
          size="icon"
          [attr.aria-label]="vm.themeToggleLabel()"
          [hlmTooltip]="vm.themeToggleLabel()"
          (click)="vm.toggleTheme()"
        >
          @if (vm.theme() === 'dark') {
            <ng-icon hlmIcon name="lucideSun" />
          } @else {
            <ng-icon hlmIcon name="lucideMoon" />
          }
        </button>

        <hlm-avatar class="app__avatar" role="img" aria-label="Signed in as Ops Commander">
          <span hlmAvatarFallback>OC</span>
        </hlm-avatar>
      </div>
    </header>

    <div class="app__content">
      <router-outlet />
    </div>
  </main>
</hlm-sidebar-wrapper>
